private void xrTableCell185_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
if (GetCurrentColumnValue("TVSHLlogaritur") != null)
            {
                if (Convert.ToDouble(GetCurrentColumnValue("TVSHLlogaritur").ToString()) < Convert.ToDouble(GetCurrentColumnValue("TVSHZbritshme").ToString()))
                {
                    xrTableCell185.Text = (Convert.ToDouble(GetCurrentColumnValue("TVSHLlogaritur").ToString()) - Convert.ToDouble(GetCurrentColumnValue("TVSHZbritshme").ToString())).ToString();
                }

                else xrTableCell185.Text = "";
            }
}

