private void xrLabel19_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
	var parameters = AlphaWebReports.raporteUtil.DeserializoParametrat(this.Extensions["filtrat"]);
      var filterDtDok = parameters.Find(parami => parami.Emri == "filterDtDok");
      xrLabel19.Text = (filterDtDok != null) ? filterDtDok.Vlera : "";
}
